test.config:
indexer
{
	mem_limit = 16M
}

searchd
{

	thread_stack = 256K
}


source src
{
	type			= mysql

	sql_query		= select * from test
}

index test
{
	source			= src
	path			= /test
	stored_fields	= title
}

test.db_create:
CREATE TABLE test (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
);

queries.sphinxql:
select id from test where id>0;
select id from test where id>0 /*+ DocidIndex(id) */;
select id from test where id>0 /*+ NO_DocidIndex(id) */;

select * from test where id>60;


select id from test where id=-8512036305353430386 /*+ NO_DocidIndex(id) */;
select id from test where id=-8512036305353430386 /*+ DocidIndex(id) */;
select id from test where id between -8512036305353430386 and -8512036305353430386 /*+ DocidIndex(id) */;
select count(*) from test where id>=-8512036305353430386 /*+ DocidIndex(id) */;
select count(*) from test where id>-8512036305353430386 /*+ DocidIndex(id) */;
select id from test where id in (-8512036305353430386) /*+ DocidIndex(id) */;
select id from test where id in (-8512036305353430386,1,64) order by id asc /*+ DocidIndex(id) */;
set global @negative_ids = (-8512036305353430386,1,64);
select id from test where id in @negative_ids order by id asc /*+ DocidIndex(id) */;


select id from test where id <> 60 order by id desc limit 5 /*+ DocidIndex(id) */;
select id from test where match ('test') and id <> 60 order by id desc limit 5 /*+ DocidIndex(id) */;
